// Builder for many optional fields
record User(String name, int age, String city) {
    static Builder builder(String name) { return new Builder(name); }
    static final class Builder {
        private final String name;
        private int age;
        private String city = "unknown";
        Builder(String name) { this.name = name; }
        Builder age(int age) { this.age = age; return this; }
        Builder city(String city) { this.city = city; return this; }
        User build() { return new User(name, age, city); }
    }
}

interface Discount { double apply(double amount); }

static double checkout(double amount, Discount discount) {
    return discount.apply(amount);
}

System.out.println(checkout(1000, a -> a * 0.9));
System.out.println(checkout(1000, a -> a - 100));

