import java.util.*;
import java.util.function.DoubleUnaryOperator;

public class Main {
    static double checkout(double amount, DoubleUnaryOperator discount) {
        return discount.applyAsDouble(amount);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String kind = sc.next();
        double amount = sc.nextDouble();
        DoubleUnaryOperator discount = kind.equals("festival") ? a -> a * 0.9 : a -> a;
        System.out.printf("%.2f%n", checkout(amount, discount));
    }
}
